15	#include <mutex>
16	#include <mki/utils/any/any.h>
17	#include "atb/utils/log.h"
18	
19	namespace atb {
20	class Runner;
21	struct PoolItem {
22	    bool isUsed = false;
23	    std::shared_ptr<Runner> runner;
24	};
25	
26	class RunnerPool {
27	public:
28	    RunnerPool();
29	    ~RunnerPool() = default;
30	    RunnerPool(const RunnerPool &other);
31	    RunnerPool &operator=(const RunnerPool &other);
32	    template <typename RunnerClass, typename ParamType> Runner *MallocRunner(ParamType param)
33	    {
34	        if (lock_ == nullptr) {
35	            ATB_LOG(ERROR) << "Lock is empty!";
36	            return nullptr;
37	        }
38	        std::lock_guard<std::mutex> lock(*lock_);
39	        for (size_t i = 0; i < poolItems_.size(); i++) {
40	            auto &poolItem = poolItems_.at(i);
41	            if (!poolItem.isUsed) {
42	                poolItem.isUsed = true;
43	                if (poolItem.runner) {
44	                    ATB_LOG(INFO) << "Get pool old runner!";
45	                    SetRunnerParam(poolItem, param);
46	                } else {
47	                    ATB_LOG(INFO) << "Pool create new runner!";
48	                    poolItem.runner = std::make_shared<RunnerClass>(param);
49	                }
50	                return poolItem.runner.get();
51	            }
52	        }
53	        return nullptr;
54	    }
55	    void FreeRunner(Runner *runner);
56	
57	private:
58	    void SetRunnerParam(PoolItem &item, const Mki::Any &param) const;
59	
60	private:
61	    std::vector<PoolItem> poolItems_;
62	    std::shared_ptr<std::mutex> lock_;
63	};
64	} // namespace atb
