10	#include "atb/context.h"
11	#include "atb/context/context_base.h"
12	#include "atb/types.h"
13	#include "atb/utils/log.h"
14	
15	namespace atb {
16	Status CreateContext(Context **context)
17	{
18	    if (!context) {
19	        ATB_LOG(ERROR) << "param context is null, CreateContext fail";
20	        return ERROR_INVALID_PARAM;
21	    }
22	
23	    ContextBase *contextBase = new (std::nothrow) ContextBase();
24	    if (!contextBase) {
25	        ATB_LOG(ERROR) << "new ContextBase fail, CreateContext fail";
26	        return ERROR_OUT_OF_HOST_MEMORY;
27	    }
28	
29	    Status st = contextBase->Init();
30	    if (st != NO_ERROR) {
31	        ATB_LOG(ERROR) << "ContextBase init fail, CreateContext fail";
32	        delete contextBase;
33	        contextBase = nullptr;
34	        return st;
35	    }
36	
37	    *context = contextBase;
38	    return NO_ERROR;
39	}
40	
41	Status CreateContext(Context **context, const std::function<void*(size_t)>& alloc, const std::function<void(void*)>& dealloc)
42	{
43	    if (!context) {
44	        ATB_LOG(ERROR) << "param context is null, CreateContext fail";
45	        return ERROR_INVALID_PARAM;
46	    }
47	
48	    ContextBase *contextBase = new (std::nothrow) ContextBase();
49	    if (!contextBase) {
50	        ATB_LOG(ERROR) << "new ContextBase fail, CreateContext fail";
51	        return ERROR_OUT_OF_HOST_MEMORY;
52	    }
53	
54	    Status st = contextBase->Init(alloc, dealloc);
55	    if (st != NO_ERROR) {
56	        ATB_LOG(ERROR) << "ContextBase init fail, CreateContext fail";
57	        delete contextBase;
58	        contextBase = nullptr;
59	        return st;
60	    }
61	
62	    *context = contextBase;
63	    return NO_ERROR;
64	}
65	
66	Status CreateContext(Context **context, uint32_t hostTilingBlockNum, uint32_t deviceTilingBlockNum)
67	{
68	    if (!context) {
69	        ATB_LOG(ERROR) << "param context is null, CreateContext fail";
70	        return ERROR_INVALID_PARAM;
71	    }
72	
73	    if (hostTilingBlockNum < 128 || hostTilingBlockNum > 1024) {
74	        ATB_LOG(ERROR) << "param hostTilingBlockNum is invalid, CreateContext fail";
75	        return ERROR_INVALID_PARAM;
76	    }
77	
78	    if (deviceTilingBlockNum < 32 || deviceTilingBlockNum > 1024) {
79	        ATB_LOG(ERROR) << "param deviceTilingBlockNum is invalid, CreateContext fail";
80	        return ERROR_INVALID_PARAM;
81	    }
82	
83	    ContextBase *contextBase = new (std::nothrow) ContextBase();
84	    if (!contextBase) {
85	        ATB_LOG(ERROR) << "new ContextBase fail, CreateContext fail";
86	        return ERROR_OUT_OF_HOST_MEMORY;
87	    }
88	
89	    Status st = contextBase->Init(nullptr, nullptr, hostTilingBlockNum, deviceTilingBlockNum);
90	    if (st != NO_ERROR) {
91	        ATB_LOG(ERROR) << "ContextBase init fail, CreateContext fail";
92	        delete contextBase;
93	        contextBase = nullptr;
94	        return st;
95	    }
96	
97	    *context = contextBase;
98	    return NO_ERROR;
99	}
100	
101	Status DestroyContext(Context *context)
102	{
103	    if (context) {
104	        ContextBase *contextBase = dynamic_cast<ContextBase *>(context);
105	        if (contextBase) {
106	            contextBase->Destroy();
107	            delete contextBase;
108	            contextBase = nullptr;
109	        }
110	    }
111	
112	    return NO_ERROR;
113	}
114	} // namespace atb

