42	    void *addr = nullptr;
43	    bufferSize = static_cast<size_t>(TensorUtil::AlignInt(bufferSize, ALIGN_INT));
44	    ATB_LOG(INFO) << "bufferSize should be 32-bit alignment, automate align upwards to " << bufferSize;
45	    // aclrtMalloc会自动对于bufferSize+32，不论bufferSize是否是32的整数倍
46	    Status st = aclrtMalloc(&addr, bufferSize, ACL_MEM_MALLOC_HUGE_FIRST);
47	    if (st != 0) {
48	        ATB_LOG(ERROR) << "aclrtMalloc device buffer failed!";
